  /// Expand keywords with synonyms and prefix stems.
  /// Works across all domains (legal, medical, technical, etc.).
  List<String> _expandKeywords(List<String> keywords) {
    final expanded = <String>{...keywords};

    for (final kw in keywords) {
      // Add synonym expansions (forward lookup)
      final syns = _synonyms[kw];
      if (syns != null) expanded.addAll(syns);

      // Reverse lookup: if a synonym value is queried, also add its key
      for (final entry in _synonyms.entries) {
        if (entry.value.contains(kw)) {
          expanded.add(entry.key);
        }
      }

      // Prefix stem matching: 'prescri' matches 'prescribed', 'prescription'
      // Stems are clamped to 4-6 chars to align with _scoreChunk's prefix logic
      if (kw.length >= 6 && !kw.contains(' ')) {
        expanded.add(kw.substring(0, kw.length.clamp(4, 6)));
      }
    }

    return expanded.toList();
  }

  /// Extract keywords from a query: unigrams + bigrams + entity patterns.
  List<String> _extractKeywords(String query) {
    final keywords = <String>{};

    // 0. Extract dollar amounts and decimal numbers BEFORE cleaning
    //    e.g. "$15 million", "$2.5", "12.5%", "3.14"
    final moneyPattern = RegExp(
      r'\$\s*[\d,.]+\s*(?:million|billion|thousand|k|m|b)?'
      r'|[\d,.]+\s*(?:million|billion|thousand|percent|%)',
      caseSensitive: false,
    );
    for (final m in moneyPattern.allMatches(query)) {
      keywords.add(m.group(0)!.replaceAll(RegExp(r'\s+'), ' ').toLowerCase());
    }

    // Also preserve standalone decimal numbers like "12.5", "3.14"
    final decimalPattern = RegExp(r'\d+\.\d+');
    for (final m in decimalPattern.allMatches(query)) {
      keywords.add(m.group(0)!);
    }

    // Clean the query for general keyword extraction
    final clean = query
        .replaceAll(RegExp(r"[''`]"), ' ')
        .replaceAll(RegExp(r'[^\w\s\d()-]'), ' ');

    // Extract raw words (preserve case for entity detection)
    final rawWords = clean.split(RegExp(r'\s+'))
        .where((w) => w.length > 1)
        .toList();

    // 1. Add unigrams (lowercased, without stopwords)
    final unigrams = rawWords
        .map((w) => w.replaceAll(RegExp(r'[^\w]'), '').toLowerCase())
        .where((w) => w.length > 1 && !_stopwords.contains(w))
        .toList();
    keywords.addAll(unigrams);

    // 2. Add bigrams from consecutive non-stopword words
    //    e.g. "Thomas Wright" → "thomas wright"
    //    e.g. "serum creatinine" → "serum creatinine"
    for (int i = 0; i < rawWords.length - 1; i++) {
      final a = rawWords[i].replaceAll(RegExp(r'[^\w]'), '').toLowerCase();
      final b = rawWords[i + 1].replaceAll(RegExp(r'[^\w]'), '').toLowerCase();
      if (a.length > 1 && b.length > 1 &&
          !_stopwords.contains(a) && !_stopwords.contains(b)) {
        keywords.add('$a $b');
      }
    }

    // 3. Detect labeled references: "Section 5", "Article 10", "Clause 3",
    //    "Patient 7", "Chapter 2", "Item 4", "Part III", etc.
    final labelPattern = RegExp(
      r'(?:section|article|clause|chapter|part|item|schedule|patient|record|case|exhibit|paragraph)\s+(\w+)',
      caseSensitive: false,
    );
    for (final m in labelPattern.allMatches(query)) {
      keywords.add(m.group(0)!.toLowerCase());
    }

    // 4. Detect parenthesized proper names like "(Thomas Wright)"
    final parenName = RegExp(r'\(([A-Z][a-z]+ [A-Z][a-z]+)\)').firstMatch(query);
    if (parenName != null) {
      keywords.add(parenName.group(1)!.toLowerCase());
    }

    // 5. Detect quoted phrases "like this" for exact matching
    final quotedPhrases = RegExp(r'"([^"]+)"').allMatches(query);
    for (final m in quotedPhrases) {
      keywords.add(m.group(1)!.toLowerCase());
    }

    return keywords.toList();
  }

  /// Score a chunk against a set of keywords (already expanded).
  double _scoreChunk(String chunkText, List<String> keywords) {
    final lower = chunkText.toLowerCase();
    double score = 0;
    int matchedCount = 0;

    for (final kw in keywords) {
      // For prefix stems: check if any word in text starts with the keyword
      bool matched;
      if (kw.length >= 4 && kw.length <= 6 && !kw.contains(' ')) {
        // Prefix/stem match — find words starting with this stem
        matched = RegExp('\\b${RegExp.escape(kw)}').hasMatch(lower);
      } else {
        matched = lower.contains(kw);
      }
      if (!matched) continue;

      matchedCount++;

      final isBigram = kw.contains(' ');
      final isNumber = RegExp(r'^\d+$').hasMatch(kw);
      final isMoney = kw.contains('\$') || kw.contains('million') ||
          kw.contains('billion') || kw.contains('thousand');
      final isDecimal = RegExp(r'^\d+\.\d+$').hasMatch(kw);

      // Base score: money/decimal worth most (very specific), bigrams high,
      // plain numbers moderate, regular words baseline
      double kwScore = (isMoney || isDecimal)
          ? 4.0
          : isBigram
              ? 3.0
              : (isNumber ? 0.5 : 1.0);

      // Count occurrences
      int count = 0;
      int idx = 0;
      while ((idx = lower.indexOf(kw, idx)) != -1) {
        count++;
        idx += kw.length;
      }
      kwScore += (count - 1) * 0.3;

      // Exact word boundary match bonus
      if (RegExp('\\b${RegExp.escape(kw)}\\b').hasMatch(lower)) {
        kwScore *= 1.3;
      }

      score += kwScore;
    }

    // Bonus for matching a higher fraction of all keywords
    if (score > 0 && keywords.isNotEmpty) {
      score += (matchedCount / keywords.length) * 2.0;
    }

    return score;
  }

  /// Detect if query is broad ("list all", "summarize", "overview", etc.)
  bool _isBroadQuery(String query) {
    final lower = query.toLowerCase();
    return lower.contains('list all') ||
           lower.contains('how many') ||
           lower.contains('summarize') ||
           lower.contains('summary') ||
           lower.contains('overview') ||
           lower.contains('all of') ||
           lower.contains('entire') ||
           lower.contains('everything') ||
           lower.contains('every ') ||
           lower.contains('each ') ||
           lower.contains('enumerate') ||
           lower.contains('complete list') ||
           lower.contains('main points') ||
           lower.contains('key points') ||
           lower.contains('highlight');
  }

  /// Returns up to [limit] chunks sorted by RELEVANCE to [query].
  /// Most relevant chunks come FIRST so they fill the context budget before
  /// less relevant ones. This ensures each query gets DIFFERENT context.
  ///
  /// Uses keyword extraction, synonym expansion, and weighted scoring.
  /// Always returns at least top-N chunks (never empty) so the model
  /// never hallucinates from lack of context.
  List<String> searchContext(String query, {int limit = 5}) {
    final all = _box.getAll();
    if (all.isEmpty) return [];

    final rawKeywords = _extractKeywords(query);
    final keywords = _expandKeywords(rawKeywords);
    final broad = _isBroadQuery(query);
    final effectiveLimit = broad ? limit + 3 : limit;

    if (keywords.isEmpty) {
      return all.take(effectiveLimit).map((e) => e.text).toList();
    }

    // Score every chunk against the query keywords
    final scored = <MapEntry<int, double>>[];
    for (int i = 0; i < all.length; i++) {
      scored.add(MapEntry(i, _scoreChunk(all[i].text, keywords)));
    }

    // Sort by score DESCENDING — most relevant first
    scored.sort((a, b) => b.value.compareTo(a.value));

    // Return the top chunks by relevance (not document order!)
    // This is the KEY: different queries → different top chunks → different context
    return scored
        .take(effectiveLimit)
        .map((e) => all[e.key].text)
        .toList();
  }

  /// Total number of stored chunks.
  int get count => _box.count();

  /// Same as searchContext but kept for API compatibility.
  List<String> scoredSearchAll(String query, {int limit = 5}) {
    return searchContext(query, limit: limit);
  }

  /// Returns the first [n] chunk texts for preview purposes.
  List<String> getSampleChunks({int n = 3}) {
    return _box.getAll().take(n).map((e) => e.text).toList();
  }

  /// Returns ALL chunk texts in stored order.
  List<String> getAllChunks() {
    return _box.getAll().map((e) => e.text).toList();
  }

  // ───────────────────────────── Lifecycle ────────────────────────────────

  void close() => _store.close();
}
